def first_round(apps, schema_editor):
    """A business already recording phones from M-KOPA gets them as one open round from its first delivery, return by ten days on."""
    from datetime import timedelta
    Stock, Sale, Round = (apps.get_model("mkopa", name) for name in ("MkopaStock", "MkopaSale", "MkopaRound"))
    for org in Stock._base_manager.filter(reversed_at__isnull=True).values_list("organization_id", flat=True).distinct():
        first = Stock._base_manager.filter(organization_id=org, reversed_at__isnull=True).order_by("moved_on").first().moved_on
        rnd = Round._base_manager.create(organization_id=org, given_on=first, return_by=first + timedelta(days=10))
        Stock._base_manager.filter(organization_id=org).update(round=rnd)
        Sale._base_manager.filter(organization_id=org, sold_on__gte=first).update(round=rnd)


